-- tier: any
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.step(input jsonb) RETURNS jsonb LANGUAGE plpgsql AS $step$
BEGIN RETURN hybrid_truco_challenge.engine(input); END;
