REVOKE ALL ON FUNCTION hybrid_truco_challenge.step(jsonb) FROM PUBLIC;

-- What every member and, where declared, everyone reads of the instance: its
-- seats' rows, each column of the surface filled from the view's field of
-- the same name.
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.settle(game hybrid_truco_challenge.instance, projected jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_challenge AS $settle$
BEGIN
  INSERT INTO public.truco_challenge_seat AS v ("id", "instance_id", "actor", "seat", "revision", "phase", "view", "inviter_name", "target_name", "variant", "seating", "room")
    SELECT r."id", r."instance_id", r."actor", r."seat", r."revision", r."phase", r."view", r."inviter_name", r."target_name", r."variant", r."seating", r."room" FROM jsonb_array_elements(projected->'views') p
    JOIN hybrid_truco_challenge.member m ON m.instance_id = game.id AND m.seat = p->>'viewer'
    CROSS JOIN LATERAL jsonb_populate_record(NULL::public.truco_challenge_seat, (p->'value') || jsonb_build_object(
      'id', game.id::text || '/' || m.seat, 'instance_id', game.id, 'actor', m.actor, 'seat', m.seat,
      'revision', game.revision::text, 'phase', game.state->>'phase', 'view', p->'value')) r
    ON CONFLICT (id) DO UPDATE SET "instance_id" = EXCLUDED."instance_id", "actor" = EXCLUDED."actor", "seat" = EXCLUDED."seat", "revision" = EXCLUDED."revision", "phase" = EXCLUDED."phase", "view" = EXCLUDED."view", "inviter_name" = EXCLUDED."inviter_name", "target_name" = EXCLUDED."target_name", "variant" = EXCLUDED."variant", "seating" = EXCLUDED."seating", "room" = EXCLUDED."room";
END;
$settle$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.settle(hybrid_truco_challenge.instance, jsonb) FROM PUBLIC;


CREATE OR REPLACE FUNCTION hybrid_truco_challenge.dispatch(instance_id uuid, actor uuid, command_id text, request jsonb, tier text, at bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, hybrid_truco_challenge
SET statement_timeout = '5s'
SET lock_timeout = '2s'
AS $dispatch$
DECLARE
  game hybrid_truco_challenge.instance;
  prior hybrid_truco_challenge.receipt;
  seat text;
  answer jsonb;
  reduced jsonb;
  recipients jsonb;
  now_ms bigint;
  drawn text;
  prepared_revision bigint;
BEGIN
  PERFORM hybrid_truco_challenge.serial();
  PERFORM hybrid_truco_challenge.hold_instance(instance_id);
  SELECT * INTO STRICT game FROM hybrid_truco_challenge.instance i WHERE i.id = instance_id;
  IF tier = 'omnishell' AND NOT EXISTS (SELECT FROM hybrid_truco_challenge.member m WHERE m.instance_id = game.id AND m.actor = dispatch.actor) THEN
    RAISE EXCEPTION 'not a member' USING ERRCODE = '42501';
  END IF;
  prepared_revision := game.revision;
  IF (tier = 'omnishell') THEN
PERFORM 1 FROM "hybrid_truco_presence"."instance" WHERE "id" IN ((game.state->>'inviter')::uuid, (game.state->>'target')::uuid) ORDER BY "id" FOR UPDATE;
END IF;
  SELECT * INTO STRICT game FROM hybrid_truco_challenge.instance i WHERE i.id = instance_id FOR UPDATE;
  IF tier = 'omnishell' THEN
    SELECT m.seat INTO seat FROM hybrid_truco_challenge.member m WHERE m.instance_id = game.id AND m.actor = dispatch.actor;
    IF seat IS NULL THEN RAISE EXCEPTION 'not a member' USING ERRCODE = '42501'; END IF;
  ELSIF tier <> 'mecha' THEN
    RAISE EXCEPTION 'invalid tier';
  END IF;
  now_ms := coalesce(at, hybrid_truco_challenge.clock());
  SELECT * INTO prior FROM hybrid_truco_challenge.receipt r WHERE r.instance_id = game.id AND r.actor = dispatch.actor AND r.command_id = dispatch.command_id;
  IF FOUND THEN
    IF prior.request <> request THEN RAISE EXCEPTION 'command id reused with different input' USING ERRCODE = '22023'; END IF;
    RETURN prior.result;
  END IF;
  IF request->>'version' IS DISTINCT FROM game.version::text THEN
    answer := jsonb_build_object('kind', 'rejected', 'reason', 'protocol_version');
  ELSIF request->>'expected_revision' IS DISTINCT FROM game.revision::text THEN
    answer := jsonb_build_object('kind', 'rejected', 'reason', 'stale_revision');
  ELSE
    IF prepared_revision <> game.revision THEN
      RAISE EXCEPTION 'Mecha lock inputs changed; retry the command' USING ERRCODE = '40001';
    END IF;
    SELECT coalesce(jsonb_agg(m.seat ORDER BY m.seat), '[]'::jsonb) INTO recipients FROM hybrid_truco_challenge.member m WHERE m.instance_id = game.id;
    reduced := hybrid_truco_challenge.step(jsonb_build_object(
      'state', game.state,
      'event', request->'event',
      'context', jsonb_build_object('actor', seat, 'tier', tier, 'now', now_ms),
      'viewers', recipients
    ));
    IF reduced->>'kind' = 'accepted' THEN
      
      IF game.state->>'phase' = 'offered' AND request->'event'->>'kind' = 'accept' THEN
      IF (hybrid_truco_presence.available((game.state->>'inviter')::uuid) AND hybrid_truco_presence.available((game.state->>'target')::uuid)) IS NOT TRUE THEN
        reduced := jsonb_build_object('kind', 'rejected', 'reason', 'player_unavailable');
      ELSE
        PERFORM hybrid_truco_match.spawn((game.state->>'room')::uuid, jsonb_build_object('variant', game.state->>'variant', 'seating', game.state->>'seating', 'turn_ms', 20000, 'reserved', false, 'talk', game.state->>'talk'), jsonb_build_object('a', game.state->>'inviter', 'b', game.state->>'target'), now_ms);
PERFORM hybrid_truco_match.deliver((game.state->>'room')::uuid, jsonb_build_object('kind', 'start', 'payload', jsonb_build_object('seats', '["a","b"]'::jsonb)), now_ms);
      END IF;
    END IF;
    END IF;
    IF reduced->>'kind' = 'accepted' THEN
      UPDATE hybrid_truco_challenge.instance i SET state = reduced->'state', revision = i.revision + 1 WHERE i.id = game.id
        RETURNING i.* INTO STRICT game;
      PERFORM hybrid_truco_challenge.settle(game, reduced);
      -- The timers the step's entries started and its exits cancelled, each
      -- measured from the step's time.
      PERFORM hybrid_truco_challenge.arm(game.id, game.revision, reduced->'actions', now_ms);
      answer := jsonb_build_object('kind', 'accepted');
    ELSIF reduced->>'kind' = 'rejected' THEN
      answer := reduced;
    ELSE
      RAISE EXCEPTION 'invalid mecha result';
    END IF;
  END IF;
  answer := answer || jsonb_build_object('command_id', command_id, 'revision', game.revision::text);
  INSERT INTO hybrid_truco_challenge.receipt (instance_id, actor, command_id, request, result, now, entropy)
    VALUES (game.id, actor, command_id, request, answer, now_ms, drawn);
  RETURN answer;
END;
$dispatch$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.dispatch(uuid, uuid, text, jsonb, text, bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION hybrid_truco_challenge.deliver(instance_id uuid, event jsonb, at bigint DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_challenge AS $deliver$
DECLARE revision bigint; answer jsonb;
BEGIN
  -- Locked as dispatch will lock it, so the revision read is the one it checks.
  PERFORM hybrid_truco_challenge.hold_instance(instance_id);
  SELECT i.revision INTO STRICT revision FROM hybrid_truco_challenge.instance i WHERE i.id = instance_id FOR UPDATE;
  -- One delivery is accepted per revision, so the revision names it.
  answer := hybrid_truco_challenge.dispatch(instance_id, '00000000-0000-0000-0000-000000000000', 'mecha/' || revision::text,
    jsonb_build_object('version', 2, 'expected_revision', revision::text, 'event', event), 'mecha', at);
  IF answer->>'kind' IS DISTINCT FROM 'accepted' THEN
    RAISE EXCEPTION 'Mecha delivery refused: %', answer USING ERRCODE = 'check_violation';
  END IF;
END;
$deliver$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.deliver(uuid, jsonb, bigint) FROM PUBLIC;

-- A command row is the browser's whole request: inserting it dispatches it,
-- and the receipt is stamped on the row in the same transaction.
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.command() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_challenge AS $command$
DECLARE answer jsonb;
BEGIN
  answer := hybrid_truco_challenge.dispatch(NEW.instance_id, NEW.actor, NEW.id, NEW.request::jsonb, 'omnishell');
  UPDATE public.truco_challenge_command c SET outcome = answer->>'kind', reason = coalesce(answer->>'reason', ''),
    revision = (answer->>'revision')::bigint WHERE c.id = NEW.id;
  RETURN NULL;
END;
$command$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.command() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_challenge_command_dispatch AFTER INSERT ON public.truco_challenge_command
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_challenge.command();
-- Readers write only commands; everything else on the surface is the
-- machine's, written from inside its SECURITY DEFINER functions.
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.sealed() RETURNS trigger LANGUAGE plpgsql AS $sealed$
BEGIN
  IF current_user::text IN ('app_user', 'anon') THEN RAISE EXCEPTION '% rows are the machine''s', TG_TABLE_NAME USING ERRCODE = '42501'; END IF;
  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$sealed$;
CREATE OR REPLACE TRIGGER truco_challenge_command_sealed BEFORE UPDATE OR DELETE ON public.truco_challenge_command
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_challenge.sealed();
CREATE OR REPLACE TRIGGER truco_challenge_seat_sealed BEFORE INSERT OR UPDATE OR DELETE ON public.truco_challenge_seat
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_challenge.sealed();



COMMENT ON SCHEMA hybrid_truco_challenge IS 'Hybrid truco_challenge protocol 2; no public canonical-state access';


-- tier: container
CREATE EXTENSION IF NOT EXISTS plv8;
-- tier: any
-- Run again on a database it built, as each release runs it, this replaces the
-- machine's code and keeps its instances: its tables keep the shape they were
-- made with, and each instance the protocol it was made under. A new protocol
-- is a migration's to carry them forward, refused here rather than half applied.
DO $protocol$ BEGIN
  IF to_regnamespace('hybrid_truco_match') IS NOT NULL AND obj_description(to_regnamespace('hybrid_truco_match'), 'pg_namespace') IS DISTINCT FROM 'Hybrid truco_match protocol 8; no public canonical-state access' THEN
    RAISE EXCEPTION 'hybrid_truco_match holds instances of another protocol than 8' USING ERRCODE = '55000';
  END IF;
END $protocol$;
CREATE SCHEMA IF NOT EXISTS hybrid_truco_match;
REVOKE ALL ON SCHEMA hybrid_truco_match FROM PUBLIC;
-- A machine's steps run read committed, ordered by locks rather than by a
-- snapshot: a step holds each player of its instance (hold) before it locks
-- any row, so two steps sharing a player run one after the other, and a check
-- reading that player's other instances (seated elsewhere, unavailable) reads
-- them settled. Steps sharing no player share no lock and never abort each
-- other. Under serializable they did: PostgreSQL locks a serializable read by
-- index page, so two players writing their own rows of one small table read
-- each other's page, one was aborted for a conflict no data caused, and the
-- writer took the abort as final. The roles that drive a step, app_user through
-- the gateway and service for the ticker, keep the database's default, which a
-- database built when they were serializable gets back here.
DO $isolation$ BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_user') THEN ALTER ROLE app_user RESET default_transaction_isolation; ALTER ROLE app_user RESET enable_seqscan; END IF;
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'service') THEN ALTER ROLE service RESET default_transaction_isolation; ALTER ROLE service RESET enable_seqscan; END IF;
END $isolation$;
-- A step that waited for a player must read what that player's last step
-- left, which a snapshot taken before the wait would not show.
CREATE OR REPLACE FUNCTION hybrid_truco_match.serial() RETURNS void LANGUAGE plpgsql AS $serial$
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'a truco_match step runs read committed, not %', current_setting('transaction_isolation') USING ERRCODE = '25000';
  END IF;
END;
$serial$;
-- A player's lock, the same in every machine's schema: an advisory lock held
-- to the end of the transaction, keyed by the player and taken in key order,
-- so two steps holding several never wait on each other's. One call takes a
-- step's whole set: a second would take its keys out of order.
CREATE OR REPLACE FUNCTION hybrid_truco_match.hold(actors uuid[]) RETURNS void LANGUAGE plpgsql AS $hold$
DECLARE k integer;
BEGIN
  FOR k IN SELECT DISTINCT hashtext(a::text) FROM unnest(actors) a WHERE a IS NOT NULL ORDER BY 1 LOOP
    PERFORM pg_advisory_xact_lock(hashtext('mecha player'), k);
  END LOOP;
END;
$hold$;
REVOKE ALL ON FUNCTION hybrid_truco_match.hold(uuid[]) FROM PUBLIC;
-- An instance's players, and one about to join it.
CREATE OR REPLACE FUNCTION hybrid_truco_match.hold_instance(room uuid, joining uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $hold_instance$
BEGIN
  PERFORM hybrid_truco_match.hold(ARRAY(SELECT m.actor FROM hybrid_truco_match.member m WHERE m.instance_id = room) || joining);
END;
$hold_instance$;
REVOKE ALL ON FUNCTION hybrid_truco_match.hold_instance(uuid, uuid) FROM PUBLIC;
-- A step's time: the transaction's, the same on every read in it, so every
-- check in one step agrees on it, and no session can set it. A step a timer
-- delivers is given the tick's time instead (dispatch's at), so a deadline
-- is decided on the ticker's clock alone.
CREATE OR REPLACE FUNCTION hybrid_truco_match.clock() RETURNS bigint LANGUAGE sql STABLE AS $clock$
SELECT floor(extract(epoch FROM transaction_timestamp()) * 1000)::bigint;
$clock$;
REVOKE ALL ON FUNCTION hybrid_truco_match.clock() FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_match.draw() RETURNS text LANGUAGE sql AS $draw$
SELECT left(string_agg(substr(hex, 1, 12) || substr(hex, 14, 3) || substr(hex, 18), ''), 256)
FROM (SELECT replace(gen_random_uuid()::text, '-', '') AS hex FROM generate_series(1, 9)) random;
$draw$;
REVOKE ALL ON FUNCTION hybrid_truco_match.draw() FROM PUBLIC;
CREATE TABLE IF NOT EXISTS hybrid_truco_match.instance (
  id uuid PRIMARY KEY,
  version integer NOT NULL CHECK (version = 8),
  revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
  state jsonb NOT NULL
);
CREATE TABLE IF NOT EXISTS hybrid_truco_match.member (
  instance_id uuid NOT NULL REFERENCES hybrid_truco_match.instance,
  actor uuid NOT NULL,
  seat text NOT NULL,
  PRIMARY KEY(instance_id, actor), UNIQUE(instance_id, seat)
);
-- An actor's seats across instances (an admission asks whether one sits elsewhere),
-- read by index so a step locks that actor's rows and no one else's.
CREATE INDEX IF NOT EXISTS member_actor ON hybrid_truco_match.member (actor);
CREATE TABLE IF NOT EXISTS hybrid_truco_match.receipt (
  instance_id uuid NOT NULL REFERENCES hybrid_truco_match.instance,
  actor uuid NOT NULL,
  command_id text NOT NULL,
  request jsonb NOT NULL,
  result jsonb NOT NULL,
  -- What the step was given beside its request, so it replays.
  now bigint NOT NULL,
  entropy text,
  PRIMARY KEY(instance_id, actor, command_id)
);
-- The step's engine is the tier's. PostgreSQL runs the rules in plv8, inside
-- the fence; the edge object creates hybrid_truco_match.engine over its host import
-- when it boots (mecha-edge's machines.ts); the browser tier has no engine and
-- steps nothing. plpgsql resolves the engine when a step runs, so the step is
-- declared once, on every tier, before any engine exists.
