-- What every member and, where declared, everyone reads of the instance: its
-- seats' rows, each column of the surface filled from the view's field of
-- the same name.
CREATE OR REPLACE FUNCTION hybrid_truco_match.settle(game hybrid_truco_match.instance, projected jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_match AS $settle$
BEGIN
  INSERT INTO public.truco_match_seat AS v ("id", "instance_id", "actor", "seat", "revision", "phase", "view", "variant", "seating")
    SELECT r."id", r."instance_id", r."actor", r."seat", r."revision", r."phase", r."view", r."variant", r."seating" FROM jsonb_array_elements(projected->'views') p
    JOIN hybrid_truco_match.member m ON m.instance_id = game.id AND m.seat = p->>'viewer'
    CROSS JOIN LATERAL jsonb_populate_record(NULL::public.truco_match_seat, (p->'value') || jsonb_build_object(
      'id', game.id::text || '/' || m.seat, 'instance_id', game.id, 'actor', m.actor, 'seat', m.seat,
      'revision', game.revision::text, 'phase', game.state->>'phase', 'view', p->'value')) r
    ON CONFLICT (id) DO UPDATE SET "instance_id" = EXCLUDED."instance_id", "actor" = EXCLUDED."actor", "seat" = EXCLUDED."seat", "revision" = EXCLUDED."revision", "phase" = EXCLUDED."phase", "view" = EXCLUDED."view", "variant" = EXCLUDED."variant", "seating" = EXCLUDED."seating";
  IF projected->'public' = 'null'::jsonb THEN
    DELETE FROM public.truco_match_public WHERE id = game.id::text;
  ELSE
    INSERT INTO public.truco_match_public AS v ("id", "variant", "seating", "seated", "places", "talk")
      SELECT r."id", r."variant", r."seating", r."seated", r."places", r."talk"
      FROM jsonb_populate_record(NULL::public.truco_match_public, (projected->'public') || jsonb_build_object('id', game.id::text)) r
      ON CONFLICT (id) DO UPDATE SET "variant" = EXCLUDED."variant", "seating" = EXCLUDED."seating", "seated" = EXCLUDED."seated", "places" = EXCLUDED."places", "talk" = EXCLUDED."talk";
  END IF;
END;
$settle$;
REVOKE ALL ON FUNCTION hybrid_truco_match.settle(hybrid_truco_match.instance, jsonb) FROM PUBLIC;


CREATE OR REPLACE FUNCTION hybrid_truco_match.dispatch(instance_id uuid, actor uuid, command_id text, request jsonb, tier text, at bigint DEFAULT NULL)
