    drawn := hybrid_truco_match.draw();
    SELECT coalesce(jsonb_agg(m.seat ORDER BY m.seat), '[]'::jsonb) INTO recipients FROM hybrid_truco_match.member m WHERE m.instance_id = game.id;
    reduced := hybrid_truco_match.step(jsonb_build_object(
      'state', game.state,
      'event', request->'event',
      'context', jsonb_build_object('actor', seat, 'tier', tier, 'now', now_ms, 'entropy', drawn),
      'viewers', recipients
    ));
    IF reduced->>'kind' = 'accepted' THEN
      
      IF game.state->>'phase' = 'waiting' AND request->'event'->>'kind' = 'start' THEN
      IF (NOT EXISTS (SELECT FROM hybrid_truco_match.member m JOIN hybrid_truco_match.member o ON o.actor = m.actor AND o.instance_id <> m.instance_id JOIN hybrid_truco_match.instance g ON g.id = o.instance_id WHERE m.instance_id = game.id AND g.state->>'phase' = 'waiting')) IS NOT TRUE THEN
        reduced := jsonb_build_object('kind', 'rejected', 'reason', 'seated_elsewhere');
      ELSE
        
      END IF;
    END IF;
IF game.state->>'phase' = 'waiting' AND request->'event'->>'kind' = 'stand' THEN
              DELETE FROM "hybrid_truco_match"."member" WHERE member.instance_id = game.id AND member.actor = dispatch.actor;
        DELETE FROM "public"."truco_match_seat" WHERE truco_match_seat.instance_id = game.id AND truco_match_seat.actor = dispatch.actor;
    END IF;
    END IF;
    IF reduced->>'kind' = 'accepted' THEN
      UPDATE hybrid_truco_match.instance i SET state = reduced->'state', revision = i.revision + 1 WHERE i.id = game.id
        RETURNING i.* INTO STRICT game;
      PERFORM hybrid_truco_match.settle(game, reduced);
      -- The timers the step's entries started and its exits cancelled, each
      -- measured from the step's time.
      PERFORM hybrid_truco_match.arm(game.id, game.revision, reduced->'actions', now_ms);
      answer := jsonb_build_object('kind', 'accepted');
    ELSIF reduced->>'kind' = 'rejected' THEN
      answer := reduced;
    ELSE
      RAISE EXCEPTION 'invalid mecha result';
    END IF;
  END IF;
  answer := answer || jsonb_build_object('command_id', command_id, 'revision', game.revision::text);
  INSERT INTO hybrid_truco_match.receipt (instance_id, actor, command_id, request, result, now, entropy)
    VALUES (game.id, actor, command_id, request, answer, now_ms, drawn);
  RETURN answer;
END;
$dispatch$;
REVOKE ALL ON FUNCTION hybrid_truco_match.dispatch(uuid, uuid, text, jsonb, text, bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION hybrid_truco_match.deliver(instance_id uuid, event jsonb, at bigint DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_match AS $deliver$
DECLARE revision bigint; answer jsonb;
BEGIN
  -- Locked as dispatch will lock it, so the revision read is the one it checks.
  PERFORM hybrid_truco_match.hold_instance(instance_id);
  SELECT i.revision INTO STRICT revision FROM hybrid_truco_match.instance i WHERE i.id = instance_id FOR UPDATE;
  -- One delivery is accepted per revision, so the revision names it.
  answer := hybrid_truco_match.dispatch(instance_id, '00000000-0000-0000-0000-000000000000', 'mecha/' || revision::text,
    jsonb_build_object('version', 8, 'expected_revision', revision::text, 'event', event), 'mecha', at);
  IF answer->>'kind' IS DISTINCT FROM 'accepted' THEN
    RAISE EXCEPTION 'Mecha delivery refused: %', answer USING ERRCODE = 'check_violation';
  END IF;
END;
$deliver$;
REVOKE ALL ON FUNCTION hybrid_truco_match.deliver(uuid, jsonb, bigint) FROM PUBLIC;

-- A command row is the browser's whole request: inserting it dispatches it,
-- and the receipt is stamped on the row in the same transaction.
CREATE OR REPLACE FUNCTION hybrid_truco_match.command() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_match AS $command$
DECLARE answer jsonb;
BEGIN
  answer := hybrid_truco_match.dispatch(NEW.instance_id, NEW.actor, NEW.id, NEW.request::jsonb, 'omnishell');
  UPDATE public.truco_match_command c SET outcome = answer->>'kind', reason = coalesce(answer->>'reason', ''),
    revision = (answer->>'revision')::bigint WHERE c.id = NEW.id;
  RETURN NULL;
END;
$command$;
REVOKE ALL ON FUNCTION hybrid_truco_match.command() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_match_command_dispatch AFTER INSERT ON public.truco_match_command
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_match.command();
-- Readers write only commands; everything else on the surface is the
-- machine's, written from inside its SECURITY DEFINER functions.
CREATE OR REPLACE FUNCTION hybrid_truco_match.sealed() RETURNS trigger LANGUAGE plpgsql AS $sealed$
BEGIN
  IF current_user::text IN ('app_user', 'anon') THEN RAISE EXCEPTION '% rows are the machine''s', TG_TABLE_NAME USING ERRCODE = '42501'; END IF;
  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$sealed$;
CREATE OR REPLACE TRIGGER truco_match_command_sealed BEFORE UPDATE OR DELETE ON public.truco_match_command
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_match.sealed();
CREATE OR REPLACE TRIGGER truco_match_seat_sealed BEFORE INSERT OR UPDATE OR DELETE ON public.truco_match_seat
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_match.sealed();
CREATE OR REPLACE TRIGGER truco_match_public_sealed BEFORE INSERT OR UPDATE OR DELETE ON public.truco_match_public
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_match.sealed();


COMMENT ON SCHEMA hybrid_truco_match IS 'Hybrid truco_match protocol 8; no public canonical-state access';


-- tier: container
CREATE EXTENSION IF NOT EXISTS plv8;
-- tier: any
-- Run again on a database it built, as each release runs it, this replaces the
-- machine's code and keeps its instances: its tables keep the shape they were
-- made with, and each instance the protocol it was made under. A new protocol
-- is a migration's to carry them forward, refused here rather than half applied.
DO $protocol$ BEGIN
  IF to_regnamespace('hybrid_truco_presence') IS NOT NULL AND obj_description(to_regnamespace('hybrid_truco_presence'), 'pg_namespace') IS DISTINCT FROM 'Hybrid truco_presence protocol 2; no public canonical-state access' THEN
    RAISE EXCEPTION 'hybrid_truco_presence holds instances of another protocol than 2' USING ERRCODE = '55000';
  END IF;
END $protocol$;
CREATE SCHEMA IF NOT EXISTS hybrid_truco_presence;
REVOKE ALL ON SCHEMA hybrid_truco_presence FROM PUBLIC;
-- A machine's steps run read committed, ordered by locks rather than by a
-- snapshot: a step holds each player of its instance (hold) before it locks
-- any row, so two steps sharing a player run one after the other, and a check
-- reading that player's other instances (seated elsewhere, unavailable) reads
-- them settled. Steps sharing no player share no lock and never abort each
-- other. Under serializable they did: PostgreSQL locks a serializable read by
-- index page, so two players writing their own rows of one small table read
-- each other's page, one was aborted for a conflict no data caused, and the
-- writer took the abort as final. The roles that drive a step, app_user through
-- the gateway and service for the ticker, keep the database's default, which a
-- database built when they were serializable gets back here.
DO $isolation$ BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_user') THEN ALTER ROLE app_user RESET default_transaction_isolation; ALTER ROLE app_user RESET enable_seqscan; END IF;
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'service') THEN ALTER ROLE service RESET default_transaction_isolation; ALTER ROLE service RESET enable_seqscan; END IF;
END $isolation$;
-- A step that waited for a player must read what that player's last step
-- left, which a snapshot taken before the wait would not show.
CREATE OR REPLACE FUNCTION hybrid_truco_presence.serial() RETURNS void LANGUAGE plpgsql AS $serial$
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'a truco_presence step runs read committed, not %', current_setting('transaction_isolation') USING ERRCODE = '25000';
  END IF;
END;
$serial$;
-- A player's lock, the same in every machine's schema: an advisory lock held
-- to the end of the transaction, keyed by the player and taken in key order,
-- so two steps holding several never wait on each other's. One call takes a
-- step's whole set: a second would take its keys out of order.
CREATE OR REPLACE FUNCTION hybrid_truco_presence.hold(actors uuid[]) RETURNS void LANGUAGE plpgsql AS $hold$
DECLARE k integer;
BEGIN
  FOR k IN SELECT DISTINCT hashtext(a::text) FROM unnest(actors) a WHERE a IS NOT NULL ORDER BY 1 LOOP
    PERFORM pg_advisory_xact_lock(hashtext('mecha player'), k);
  END LOOP;
END;
$hold$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.hold(uuid[]) FROM PUBLIC;
-- An instance's players, and one about to join it.
CREATE OR REPLACE FUNCTION hybrid_truco_presence.hold_instance(room uuid, joining uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $hold_instance$
BEGIN
  PERFORM hybrid_truco_presence.hold(ARRAY(SELECT m.actor FROM hybrid_truco_presence.member m WHERE m.instance_id = room) || joining);
END;
$hold_instance$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.hold_instance(uuid, uuid) FROM PUBLIC;
-- A step's time: the transaction's, the same on every read in it, so every
-- check in one step agrees on it, and no session can set it. A step a timer
-- delivers is given the tick's time instead (dispatch's at), so a deadline
-- is decided on the ticker's clock alone.
CREATE OR REPLACE FUNCTION hybrid_truco_presence.clock() RETURNS bigint LANGUAGE sql STABLE AS $clock$
SELECT floor(extract(epoch FROM transaction_timestamp()) * 1000)::bigint;
$clock$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.clock() FROM PUBLIC;
CREATE TABLE IF NOT EXISTS hybrid_truco_presence.instance (
  id uuid PRIMARY KEY,
  version integer NOT NULL CHECK (version = 2),
  revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
  state jsonb NOT NULL
);
CREATE TABLE IF NOT EXISTS hybrid_truco_presence.member (
  instance_id uuid NOT NULL REFERENCES hybrid_truco_presence.instance,
  actor uuid NOT NULL,
  seat text NOT NULL,
  PRIMARY KEY(instance_id, actor), UNIQUE(instance_id, seat)
);
-- An actor's seats across instances (an admission asks whether one sits elsewhere),
-- read by index so a step locks that actor's rows and no one else's.
CREATE INDEX IF NOT EXISTS member_actor ON hybrid_truco_presence.member (actor);
CREATE TABLE IF NOT EXISTS hybrid_truco_presence.receipt (
  instance_id uuid NOT NULL REFERENCES hybrid_truco_presence.instance,
  actor uuid NOT NULL,
  command_id text NOT NULL,
  request jsonb NOT NULL,
  result jsonb NOT NULL,
  -- What the step was given beside its request, so it replays.
  now bigint NOT NULL,
  entropy text,
  PRIMARY KEY(instance_id, actor, command_id)
);
