      'id', game.id::text || '/' || m.seat, 'instance_id', game.id, 'actor', m.actor, 'seat', m.seat,
      'revision', game.revision::text, 'phase', game.state->>'phase', 'view', p->'value')) r
    ON CONFLICT (id) DO UPDATE SET "instance_id" = EXCLUDED."instance_id", "actor" = EXCLUDED."actor", "seat" = EXCLUDED."seat", "revision" = EXCLUDED."revision", "phase" = EXCLUDED."phase", "view" = EXCLUDED."view";
  IF projected->'public' = 'null'::jsonb THEN
    DELETE FROM public.truco_voice_public WHERE id = game.id::text;
  ELSE
    INSERT INTO public.truco_voice_public AS v ("id", "talk", "seat", "name", "word", "n")
      SELECT r."id", r."talk", r."seat", r."name", r."word", r."n"
      FROM jsonb_populate_record(NULL::public.truco_voice_public, (projected->'public') || jsonb_build_object('id', game.id::text)) r
      ON CONFLICT (id) DO UPDATE SET "talk" = EXCLUDED."talk", "seat" = EXCLUDED."seat", "name" = EXCLUDED."name", "word" = EXCLUDED."word", "n" = EXCLUDED."n";
  END IF;
END;
$settle$;
REVOKE ALL ON FUNCTION hybrid_truco_voice.settle(hybrid_truco_voice.instance, jsonb) FROM PUBLIC;


CREATE OR REPLACE FUNCTION hybrid_truco_voice.dispatch(instance_id uuid, actor uuid, command_id text, request jsonb, tier text, at bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, hybrid_truco_voice
SET statement_timeout = '5s'
SET lock_timeout = '2s'
AS $dispatch$
DECLARE
  game hybrid_truco_voice.instance;
  prior hybrid_truco_voice.receipt;
  seat text;
  answer jsonb;
  reduced jsonb;
  recipients jsonb;
  now_ms bigint;
  drawn text;
  prepared_revision bigint;
BEGIN
  PERFORM hybrid_truco_voice.serial();
  PERFORM hybrid_truco_voice.hold_instance(instance_id);
  
  SELECT * INTO STRICT game FROM hybrid_truco_voice.instance i WHERE i.id = instance_id FOR UPDATE;
  IF tier = 'omnishell' THEN
    SELECT m.seat INTO seat FROM hybrid_truco_voice.member m WHERE m.instance_id = game.id AND m.actor = dispatch.actor;
    IF seat IS NULL THEN RAISE EXCEPTION 'not a member' USING ERRCODE = '42501'; END IF;
  ELSIF tier <> 'mecha' THEN
    RAISE EXCEPTION 'invalid tier';
  END IF;
  now_ms := coalesce(at, hybrid_truco_voice.clock());
  SELECT * INTO prior FROM hybrid_truco_voice.receipt r WHERE r.instance_id = game.id AND r.actor = dispatch.actor AND r.command_id = dispatch.command_id;
  IF FOUND THEN
    IF prior.request <> request THEN RAISE EXCEPTION 'command id reused with different input' USING ERRCODE = '22023'; END IF;
    RETURN prior.result;
  END IF;
  IF request->>'version' IS DISTINCT FROM game.version::text THEN
    answer := jsonb_build_object('kind', 'rejected', 'reason', 'protocol_version');
  ELSIF request->>'expected_revision' IS DISTINCT FROM game.revision::text THEN
    answer := jsonb_build_object('kind', 'rejected', 'reason', 'stale_revision');
  ELSE
    
    SELECT coalesce(jsonb_agg(m.seat ORDER BY m.seat), '[]'::jsonb) INTO recipients FROM hybrid_truco_voice.member m WHERE m.instance_id = game.id;
    reduced := hybrid_truco_voice.step(jsonb_build_object(
      'state', game.state,
      'event', request->'event',
      'context', jsonb_build_object('actor', seat, 'tier', tier, 'now', now_ms),
      'viewers', recipients
    ));
    IF reduced->>'kind' = 'accepted' THEN
      
      IF game.state->>'phase' = 'quiet' AND request->'event'->>'kind' = 'sit' THEN
      IF (EXISTS (SELECT FROM hybrid_truco_match.member m JOIN hybrid_truco_match.instance g ON g.id = m.instance_id WHERE m.instance_id::text = request->'event'->'payload'->>'room' AND m.actor = dispatch.actor AND m.seat = request->'event'->'payload'->>'seat' AND g.state->>'talk' = request->'event'->'payload'->>'talk')) IS NOT TRUE THEN
        reduced := jsonb_build_object('kind', 'rejected', 'reason', 'not_seated');
      ELSE
        
      END IF;
    END IF;
IF game.state->>'phase' = 'seated' AND request->'event'->>'kind' = 'sit' THEN
      IF (EXISTS (SELECT FROM hybrid_truco_match.member m JOIN hybrid_truco_match.instance g ON g.id = m.instance_id WHERE m.instance_id::text = request->'event'->'payload'->>'room' AND m.actor = dispatch.actor AND m.seat = request->'event'->'payload'->>'seat' AND g.state->>'talk' = request->'event'->'payload'->>'talk')) IS NOT TRUE THEN
        reduced := jsonb_build_object('kind', 'rejected', 'reason', 'not_seated');
      ELSE
        
      END IF;
    END IF;
    END IF;
    IF reduced->>'kind' = 'accepted' THEN
      UPDATE hybrid_truco_voice.instance i SET state = reduced->'state', revision = i.revision + 1 WHERE i.id = game.id
        RETURNING i.* INTO STRICT game;
      PERFORM hybrid_truco_voice.settle(game, reduced);
      answer := jsonb_build_object('kind', 'accepted');
    ELSIF reduced->>'kind' = 'rejected' THEN
      answer := reduced;
    ELSE
      RAISE EXCEPTION 'invalid mecha result';
    END IF;
  END IF;
  answer := answer || jsonb_build_object('command_id', command_id, 'revision', game.revision::text);
  INSERT INTO hybrid_truco_voice.receipt (instance_id, actor, command_id, request, result, now, entropy)
    VALUES (game.id, actor, command_id, request, answer, now_ms, drawn);
  RETURN answer;
END;
$dispatch$;
REVOKE ALL ON FUNCTION hybrid_truco_voice.dispatch(uuid, uuid, text, jsonb, text, bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION hybrid_truco_voice.deliver(instance_id uuid, event jsonb, at bigint DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_voice AS $deliver$
DECLARE revision bigint; answer jsonb;
BEGIN
  -- Locked as dispatch will lock it, so the revision read is the one it checks.
  PERFORM hybrid_truco_voice.hold_instance(instance_id);
  SELECT i.revision INTO STRICT revision FROM hybrid_truco_voice.instance i WHERE i.id = instance_id FOR UPDATE;
  -- One delivery is accepted per revision, so the revision names it.
  answer := hybrid_truco_voice.dispatch(instance_id, '00000000-0000-0000-0000-000000000000', 'mecha/' || revision::text,
    jsonb_build_object('version', 2, 'expected_revision', revision::text, 'event', event), 'mecha', at);
  IF answer->>'kind' IS DISTINCT FROM 'accepted' THEN
    RAISE EXCEPTION 'Mecha delivery refused: %', answer USING ERRCODE = 'check_violation';
  END IF;
END;
$deliver$;
REVOKE ALL ON FUNCTION hybrid_truco_voice.deliver(uuid, jsonb, bigint) FROM PUBLIC;

-- A command row is the browser's whole request: inserting it dispatches it,
-- and the receipt is stamped on the row in the same transaction.
CREATE OR REPLACE FUNCTION hybrid_truco_voice.command() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, hybrid_truco_voice AS $command$
DECLARE answer jsonb;
BEGIN
  answer := hybrid_truco_voice.dispatch(NEW.instance_id, NEW.actor, NEW.id, NEW.request::jsonb, 'omnishell');
  UPDATE public.truco_voice_command c SET outcome = answer->>'kind', reason = coalesce(answer->>'reason', ''),
    revision = (answer->>'revision')::bigint WHERE c.id = NEW.id;
  RETURN NULL;
END;
$command$;
REVOKE ALL ON FUNCTION hybrid_truco_voice.command() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_voice_command_dispatch AFTER INSERT ON public.truco_voice_command
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_voice.command();
-- Readers write only commands; everything else on the surface is the
-- machine's, written from inside its SECURITY DEFINER functions.
CREATE OR REPLACE FUNCTION hybrid_truco_voice.sealed() RETURNS trigger LANGUAGE plpgsql AS $sealed$
BEGIN
  IF current_user::text IN ('app_user', 'anon') THEN RAISE EXCEPTION '% rows are the machine''s', TG_TABLE_NAME USING ERRCODE = '42501'; END IF;
  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$sealed$;
CREATE OR REPLACE TRIGGER truco_voice_command_sealed BEFORE UPDATE OR DELETE ON public.truco_voice_command
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_voice.sealed();
CREATE OR REPLACE TRIGGER truco_voice_seat_sealed BEFORE INSERT OR UPDATE OR DELETE ON public.truco_voice_seat
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_voice.sealed();
CREATE OR REPLACE TRIGGER truco_voice_public_sealed BEFORE INSERT OR UPDATE OR DELETE ON public.truco_voice_public
  FOR EACH ROW EXECUTE FUNCTION hybrid_truco_voice.sealed();


COMMENT ON SCHEMA hybrid_truco_voice IS 'Hybrid truco_voice protocol 2; no public canonical-state access';

-- tier: any
CREATE OR REPLACE FUNCTION hybrid_truco_match.publish(instance_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE game hybrid_truco_match.instance;
BEGIN

SELECT * INTO STRICT game FROM hybrid_truco_match.instance i WHERE i.id = instance_id FOR UPDATE;
PERFORM hybrid_truco_match.settle(game, hybrid_truco_match.step(jsonb_build_object('state', game.state, 'event', NULL, 'context', '{}'::jsonb,
 'viewers', (SELECT coalesce(jsonb_agg(m.seat ORDER BY m.seat), '[]'::jsonb) FROM hybrid_truco_match.member m WHERE m.instance_id = game.id))));
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_match.publish(uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_match.spawn(instance_id uuid, input jsonb, participants jsonb, at bigint DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE seeded jsonb;
BEGIN

IF instance_id IS NULL OR jsonb_typeof(participants) IS DISTINCT FROM 'object' OR participants = '{}'::jsonb THEN
 RAISE EXCEPTION 'initialization requires an identity and participants'; END IF;
PERFORM hybrid_truco_match.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(participants)));
seeded := hybrid_truco_match.step(jsonb_build_object('initialize', true, 'payload', input,
 'context', jsonb_build_object('tier', 'mecha', 'now', coalesce(at, hybrid_truco_match.clock())), 'viewers', '[]'::jsonb));
INSERT INTO hybrid_truco_match.instance (id, version, state) VALUES (instance_id, 8, seeded->'state');
INSERT INTO hybrid_truco_match.member (instance_id, actor, seat) SELECT instance_id, value::uuid, key FROM jsonb_each_text(participants);
PERFORM hybrid_truco_match.arm(instance_id, 0, seeded->'actions', coalesce(at, hybrid_truco_match.clock()));
PERFORM hybrid_truco_match.publish(instance_id);
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_match.spawn(uuid, jsonb, jsonb, bigint) FROM PUBLIC;
CREATE TABLE IF NOT EXISTS hybrid_truco_match.admission_receipt (id uuid PRIMARY KEY, actor uuid NOT NULL, request jsonb NOT NULL, result jsonb, now bigint NOT NULL);
CREATE OR REPLACE FUNCTION hybrid_truco_match.truco_create(instance_id uuid, variant text, talk text, seating text DEFAULT '1v1', reserved text DEFAULT 'false') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE current_actor uuid := public.auth_uid(); admission_id uuid; request_value jsonb; prior hybrid_truco_match.admission_receipt; answer jsonb;
BEGIN

IF current_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501'; END IF;
admission_id := instance_id;
IF admission_id IS NULL THEN RAISE EXCEPTION 'admission identity required'; END IF;
request_value := jsonb_build_object('instance_id', instance_id, 'variant', variant, 'talk', talk, 'seating', seating, 'reserved', reserved);
-- Its players, before its checks read where they sit.
PERFORM hybrid_truco_match.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(jsonb_build_object('a', current_actor))) || current_actor);

INSERT INTO hybrid_truco_match.admission_receipt (id, actor, request, now) VALUES (admission_id, current_actor, request_value, hybrid_truco_match.clock()) ON CONFLICT DO NOTHING;
SELECT * INTO STRICT prior FROM hybrid_truco_match.admission_receipt r WHERE r.id = admission_id FOR UPDATE;
IF prior.actor <> current_actor OR prior.request <> request_value THEN
 RAISE EXCEPTION 'admission id reused with different input or owner' USING ERRCODE = '42501'; END IF;
IF prior.result IS NOT NULL THEN RETURN prior.result; END IF;
IF (talk ~ '^[0-9a-f]{16}$') IS NOT TRUE THEN
RAISE EXCEPTION 'invalid table talk';
END IF;
IF (NOT EXISTS (SELECT FROM hybrid_truco_match.instance g WHERE g.state->>'talk' = talk) AND NOT EXISTS (SELECT FROM hybrid_truco_challenge.instance c WHERE c.state->>'talk' = talk)) IS NOT TRUE THEN
RAISE EXCEPTION 'talk_taken';
END IF;
IF (NOT EXISTS (SELECT FROM hybrid_truco_match.member m JOIN hybrid_truco_match.instance g ON g.id = m.instance_id WHERE m.actor = current_actor AND g.state->>'phase' = 'waiting')) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'seated_elsewhere', 'command_id', admission_id);
UPDATE hybrid_truco_match.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
PERFORM hybrid_truco_match.spawn(admission_id, jsonb_build_object('variant', variant, 'seating', seating, 'turn_ms', 20000, 'reserved', reserved = 'true', 'talk', talk), jsonb_build_object('a', current_actor));
answer := jsonb_build_object('kind', 'accepted', 'command_id', admission_id);
UPDATE hybrid_truco_match.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_match.truco_create(uuid, text, text, text, text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_match.join(instance_id uuid, requested_seat text DEFAULT '') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE current_actor uuid := public.auth_uid(); game hybrid_truco_match.instance; chosen text;
BEGIN

IF current_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501'; END IF;
PERFORM hybrid_truco_match.hold_instance(instance_id, current_actor);
SELECT * INTO game FROM hybrid_truco_match.instance i WHERE i.id = instance_id FOR UPDATE;
IF NOT FOUND THEN RETURN jsonb_build_object('kind', 'rejected', 'reason', 'room_unavailable'); END IF;
IF EXISTS (SELECT FROM hybrid_truco_match.member m WHERE m.instance_id = game.id AND m.actor = current_actor) THEN
 RETURN jsonb_build_object('kind', 'accepted'); END IF;
IF game.state->>'phase' NOT IN ('waiting') THEN RETURN jsonb_build_object('kind', 'rejected', 'reason', 'room_unavailable'); END IF;
SELECT slot INTO chosen FROM jsonb_array_elements_text(game.state->'seats') WITH ORDINALITY AS candidates(slot, position)
 WHERE (requested_seat = '' OR slot = requested_seat) AND NOT EXISTS
 (SELECT FROM hybrid_truco_match.member m WHERE m.instance_id = game.id AND m.seat = slot) ORDER BY position LIMIT 1;
IF chosen IS NULL THEN RETURN jsonb_build_object('kind', 'rejected', 'reason', 'seat_unavailable'); END IF;
INSERT INTO hybrid_truco_match.member VALUES (instance_id, current_actor, chosen);
PERFORM hybrid_truco_match.deliver(instance_id, jsonb_build_object('kind', 'start', 'payload', jsonb_build_object('seats', (SELECT jsonb_agg(m.seat ORDER BY m.seat) FROM hybrid_truco_match.member m WHERE m.instance_id = game.id))));
RETURN jsonb_build_object('kind', 'accepted');
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_match.join(uuid, text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_match.open() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $open$
DECLARE answer jsonb;
BEGIN
  PERFORM hybrid_truco_match.serial();
  IF NEW.kind = 'create' THEN answer := hybrid_truco_match.truco_create(NEW.instance_id, coalesce(NEW.input::jsonb->>'variant')::text, coalesce(NEW.input::jsonb->>'talk')::text, coalesce(NEW.input::jsonb->>'seating', '1v1')::text, coalesce(NEW.input::jsonb->>'reserved', 'false')::text);
  ELSIF NEW.kind = 'join' THEN answer := hybrid_truco_match.join(NEW.instance_id, coalesce(NEW.input::jsonb->>'requested_seat', ''));
  ELSE RAISE EXCEPTION 'unknown open kind %', NEW.kind USING ERRCODE = '22023';
  END IF;
  UPDATE public.truco_match_open o SET outcome = answer->>'kind', reason = coalesce(answer->>'reason', '') WHERE o.id = NEW.id;
  RETURN NULL;
END;
$open$;
REVOKE ALL ON FUNCTION hybrid_truco_match.open() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_match_open_admit AFTER INSERT ON public.truco_match_open FOR EACH ROW EXECUTE FUNCTION hybrid_truco_match.open();
CREATE OR REPLACE TRIGGER truco_match_open_sealed BEFORE UPDATE OR DELETE ON public.truco_match_open FOR EACH ROW EXECUTE FUNCTION hybrid_truco_match.sealed();
CREATE OR REPLACE FUNCTION hybrid_truco_match.arm(instance_id uuid, revision bigint, actions jsonb, at bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $arm$
DECLARE action jsonb; timer text[];
BEGIN
  FOR action IN SELECT value FROM jsonb_array_elements(coalesce(actions, '[]'::jsonb)) LOOP
    timer := regexp_match(coalesce(action->'params'->>'id', action->'params'->>'sendId'), '^xstate\.after\.([^.]+)\.(.+)$');
    IF timer IS NULL THEN RAISE EXCEPTION 'unexpected action %', action; END IF;
    IF action->>'type' = 'xstate.cancel' THEN
      DELETE FROM public.schedule WHERE emits_entity = 'machine_timer_tick' AND emits_values @> (jsonb_build_object('machine', 'truco_match', 'row', jsonb_build_object('id', instance_id::text)) || jsonb_build_object('state', timer[2], 'delay', timer[1]));
    ELSIF action->>'type' = 'xstate.raise' THEN
      INSERT INTO public.schedule (name, due_at, max_lateness_seconds, emits_entity, emits_values)
        VALUES ('machine:' || 'truco_match' || ':' || instance_id::text || ':' || revision::text || ':' || (action->'params'->>'id'),
          to_timestamp((at + (action->'params'->>'delay')::bigint) / 1000.0), 2147483647, 'machine_timer_tick', jsonb_build_object('machine', 'truco_match', 'row', jsonb_build_object('id', instance_id::text)) || jsonb_build_object('state', timer[2], 'delay', timer[1]));
    ELSE RAISE EXCEPTION 'unexpected action %', action;
    END IF;
  END LOOP;
END;
$arm$;
REVOKE ALL ON FUNCTION hybrid_truco_match.arm(uuid, bigint, jsonb, bigint) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_match.fire() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $fire$
DECLARE instance_id uuid;
BEGIN
  PERFORM hybrid_truco_match.serial();
  IF NEW.machine <> 'truco_match' OR NEW.late THEN RETURN NEW; END IF;
  instance_id := (NEW."row"->>'id')::uuid;
  -- Its players, then the instance, as a step takes them: a step that left
  -- the timer's state has cancelled its schedule by the time both are held.
  PERFORM hybrid_truco_match.hold_instance(instance_id);
  PERFORM 1 FROM hybrid_truco_match.instance i WHERE i.id = instance_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  DELETE FROM public.schedule WHERE name = NEW.schedule AND emits_entity = 'machine_timer_tick';
  IF NOT FOUND THEN RETURN NEW; END IF;
  -- The tick's instant is when the ticker found the delay met, whatever the
  -- database's clock reads. The step runs when the tick was decided, its
  -- transaction's clock(), and never before that instant: a late tick run at
  -- the instant would start the next state's timers in the past.
  PERFORM hybrid_truco_match.deliver(instance_id, jsonb_build_object('kind', 'xstate.after.' || NEW.delay || '.' || NEW.state, 'payload', '{}'::jsonb),
    greatest(round(extract(epoch FROM NEW.tick_at) * 1000)::bigint, hybrid_truco_match.clock()));
  RETURN NEW;
END;
$fire$;
REVOKE ALL ON FUNCTION hybrid_truco_match.fire() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_match_timer_fire AFTER INSERT ON public.machine_timer_tick FOR EACH ROW EXECUTE FUNCTION hybrid_truco_match.fire();
CREATE OR REPLACE FUNCTION hybrid_truco_presence.publish(instance_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE game hybrid_truco_presence.instance;
BEGIN

SELECT * INTO STRICT game FROM hybrid_truco_presence.instance i WHERE i.id = instance_id FOR UPDATE;
PERFORM hybrid_truco_presence.settle(game, hybrid_truco_presence.step(jsonb_build_object('state', game.state, 'event', NULL, 'context', '{}'::jsonb,
 'viewers', (SELECT coalesce(jsonb_agg(m.seat ORDER BY m.seat), '[]'::jsonb) FROM hybrid_truco_presence.member m WHERE m.instance_id = game.id))));
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.publish(uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_presence.spawn(instance_id uuid, input jsonb, participants jsonb, at bigint DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE seeded jsonb;
BEGIN

IF instance_id IS NULL OR jsonb_typeof(participants) IS DISTINCT FROM 'object' OR participants = '{}'::jsonb THEN
 RAISE EXCEPTION 'initialization requires an identity and participants'; END IF;
PERFORM hybrid_truco_presence.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(participants)));
seeded := hybrid_truco_presence.step(jsonb_build_object('initialize', true, 'payload', input,
 'context', jsonb_build_object('tier', 'mecha', 'now', coalesce(at, hybrid_truco_presence.clock())), 'viewers', '[]'::jsonb));
INSERT INTO hybrid_truco_presence.instance (id, version, state) VALUES (instance_id, 2, seeded->'state');
INSERT INTO hybrid_truco_presence.member (instance_id, actor, seat) SELECT instance_id, value::uuid, key FROM jsonb_each_text(participants);
PERFORM hybrid_truco_presence.arm(instance_id, 0, seeded->'actions', coalesce(at, hybrid_truco_presence.clock()));
PERFORM hybrid_truco_presence.publish(instance_id);
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.spawn(uuid, jsonb, jsonb, bigint) FROM PUBLIC;
CREATE TABLE IF NOT EXISTS hybrid_truco_presence.admission_receipt (id uuid PRIMARY KEY, actor uuid NOT NULL, request jsonb NOT NULL, result jsonb, now bigint NOT NULL);
CREATE OR REPLACE FUNCTION hybrid_truco_presence.admit() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE current_actor uuid := public.auth_uid(); admission_id uuid; request_value jsonb; prior hybrid_truco_presence.admission_receipt; answer jsonb;
BEGIN

IF current_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501'; END IF;
admission_id := current_actor;
IF admission_id IS NULL THEN RAISE EXCEPTION 'admission identity required'; END IF;
request_value := jsonb_build_object();
-- Its players, before its checks read where they sit.
PERFORM hybrid_truco_presence.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(jsonb_build_object('owner', current_actor))) || current_actor);

INSERT INTO hybrid_truco_presence.admission_receipt (id, actor, request, now) VALUES (admission_id, current_actor, request_value, hybrid_truco_presence.clock()) ON CONFLICT DO NOTHING;
SELECT * INTO STRICT prior FROM hybrid_truco_presence.admission_receipt r WHERE r.id = admission_id FOR UPDATE;
IF prior.actor <> current_actor OR prior.request <> request_value THEN
 RAISE EXCEPTION 'admission id reused with different input or owner' USING ERRCODE = '42501'; END IF;
IF prior.result IS NOT NULL THEN RETURN prior.result; END IF;

PERFORM hybrid_truco_presence.spawn(admission_id, jsonb_build_object(), jsonb_build_object('owner', current_actor));
answer := jsonb_build_object('kind', 'accepted', 'command_id', admission_id);
UPDATE hybrid_truco_presence.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.admit() FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_presence.prune(who uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $prune$
BEGIN
  DELETE FROM public.truco_presence_lease l WHERE l.id IN (SELECT c.id FROM public.truco_presence_lease c
    WHERE c.actor = who AND NOT EXISTS (SELECT 1 FROM hybrid_truco_presence.instance i, jsonb_array_elements(i.state->'leases') e WHERE i.id = who AND e->>'id' = c.id) FOR UPDATE OF c SKIP LOCKED);
END;
$prune$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.prune(uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_presence.lease() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $lease$
BEGIN
  PERFORM hybrid_truco_presence.serial();
  PERFORM hybrid_truco_presence.hold(ARRAY[CASE WHEN TG_OP = 'DELETE' THEN OLD.actor ELSE NEW.actor END]);
  IF TG_OP = 'DELETE' THEN
    -- A row the machine already let lapse leaves nothing to deliver.
    PERFORM 1 FROM hybrid_truco_presence.instance i WHERE i.id = OLD.actor FOR UPDATE;
    IF FOUND AND EXISTS (SELECT 1 FROM hybrid_truco_presence.instance i, jsonb_array_elements(i.state->'leases') e WHERE i.id = OLD.actor AND e->>'id' = OLD.id) THEN PERFORM hybrid_truco_presence.deliver(OLD.actor, jsonb_build_object('kind', 'leave', 'payload', jsonb_build_object('session', OLD.id))); END IF;
    RETURN OLD;
  END IF;
  PERFORM hybrid_truco_presence.admit();
  PERFORM hybrid_truco_presence.deliver(NEW.actor, jsonb_build_object('kind', 'touch', 'payload', jsonb_build_object('session', NEW.id)));
  PERFORM hybrid_truco_presence.prune(NEW.actor);
  RETURN NEW;
END;
$lease$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.lease() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_presence_lease_renew AFTER INSERT OR UPDATE OR DELETE ON public.truco_presence_lease FOR EACH ROW EXECUTE FUNCTION hybrid_truco_presence.lease();
CREATE OR REPLACE FUNCTION hybrid_truco_presence.arm(instance_id uuid, revision bigint, actions jsonb, at bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $arm$
DECLARE action jsonb; timer text[];
BEGIN
  FOR action IN SELECT value FROM jsonb_array_elements(coalesce(actions, '[]'::jsonb)) LOOP
    timer := regexp_match(coalesce(action->'params'->>'id', action->'params'->>'sendId'), '^xstate\.after\.([^.]+)\.(.+)$');
    IF timer IS NULL THEN RAISE EXCEPTION 'unexpected action %', action; END IF;
    IF action->>'type' = 'xstate.cancel' THEN
      DELETE FROM public.schedule WHERE emits_entity = 'machine_timer_tick' AND emits_values @> (jsonb_build_object('machine', 'truco_presence', 'row', jsonb_build_object('id', instance_id::text)) || jsonb_build_object('state', timer[2], 'delay', timer[1]));
    ELSIF action->>'type' = 'xstate.raise' THEN
      INSERT INTO public.schedule (name, due_at, max_lateness_seconds, emits_entity, emits_values)
        VALUES ('machine:' || 'truco_presence' || ':' || instance_id::text || ':' || revision::text || ':' || (action->'params'->>'id'),
          to_timestamp((at + (action->'params'->>'delay')::bigint) / 1000.0), 2147483647, 'machine_timer_tick', jsonb_build_object('machine', 'truco_presence', 'row', jsonb_build_object('id', instance_id::text)) || jsonb_build_object('state', timer[2], 'delay', timer[1]));
    ELSE RAISE EXCEPTION 'unexpected action %', action;
    END IF;
  END LOOP;
END;
$arm$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.arm(uuid, bigint, jsonb, bigint) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_presence.fire() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $fire$
DECLARE instance_id uuid;
BEGIN
  PERFORM hybrid_truco_presence.serial();
  IF NEW.machine <> 'truco_presence' OR NEW.late THEN RETURN NEW; END IF;
  instance_id := (NEW."row"->>'id')::uuid;
  -- Its players, then the instance, as a step takes them: a step that left
  -- the timer's state has cancelled its schedule by the time both are held.
  PERFORM hybrid_truco_presence.hold_instance(instance_id);
  PERFORM 1 FROM hybrid_truco_presence.instance i WHERE i.id = instance_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  DELETE FROM public.schedule WHERE name = NEW.schedule AND emits_entity = 'machine_timer_tick';
  IF NOT FOUND THEN RETURN NEW; END IF;
  -- The tick's instant is when the ticker found the delay met, whatever the
  -- database's clock reads. The step runs when the tick was decided, its
  -- transaction's clock(), and never before that instant: a late tick run at
  -- the instant would start the next state's timers in the past.
  PERFORM hybrid_truco_presence.deliver(instance_id, jsonb_build_object('kind', 'xstate.after.' || NEW.delay || '.' || NEW.state, 'payload', '{}'::jsonb),
    greatest(round(extract(epoch FROM NEW.tick_at) * 1000)::bigint, hybrid_truco_presence.clock()));
  PERFORM hybrid_truco_presence.prune(instance_id);
  RETURN NEW;
END;
$fire$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.fire() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_presence_timer_fire AFTER INSERT ON public.machine_timer_tick FOR EACH ROW EXECUTE FUNCTION hybrid_truco_presence.fire();
CREATE OR REPLACE FUNCTION hybrid_truco_presence.available(player uuid) RETURNS boolean
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
SELECT EXISTS (SELECT FROM hybrid_truco_presence.instance p
  WHERE p.id = player AND p.state->>'phase' = 'visible'
  AND EXISTS (SELECT FROM jsonb_array_elements(p.state->'leases') l
    WHERE (l->>'until')::bigint > hybrid_truco_presence.clock()))
  AND NOT EXISTS (SELECT FROM hybrid_truco_match.member m JOIN hybrid_truco_match.instance g ON g.id = m.instance_id
    WHERE m.actor = player AND g.state->>'phase' <> 'finished');
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_presence.available(uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.publish(instance_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE game hybrid_truco_challenge.instance;
BEGIN

SELECT * INTO STRICT game FROM hybrid_truco_challenge.instance i WHERE i.id = instance_id FOR UPDATE;
PERFORM hybrid_truco_challenge.settle(game, hybrid_truco_challenge.step(jsonb_build_object('state', game.state, 'event', NULL, 'context', '{}'::jsonb,
 'viewers', (SELECT coalesce(jsonb_agg(m.seat ORDER BY m.seat), '[]'::jsonb) FROM hybrid_truco_challenge.member m WHERE m.instance_id = game.id))));
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.publish(uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.spawn(instance_id uuid, input jsonb, participants jsonb, at bigint DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE seeded jsonb;
BEGIN

IF instance_id IS NULL OR jsonb_typeof(participants) IS DISTINCT FROM 'object' OR participants = '{}'::jsonb THEN
 RAISE EXCEPTION 'initialization requires an identity and participants'; END IF;
PERFORM hybrid_truco_challenge.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(participants)));
seeded := hybrid_truco_challenge.step(jsonb_build_object('initialize', true, 'payload', input,
 'context', jsonb_build_object('tier', 'mecha', 'now', coalesce(at, hybrid_truco_challenge.clock())), 'viewers', '[]'::jsonb));
INSERT INTO hybrid_truco_challenge.instance (id, version, state) VALUES (instance_id, 2, seeded->'state');
INSERT INTO hybrid_truco_challenge.member (instance_id, actor, seat) SELECT instance_id, value::uuid, key FROM jsonb_each_text(participants);
PERFORM hybrid_truco_challenge.arm(instance_id, 0, seeded->'actions', coalesce(at, hybrid_truco_challenge.clock()));
PERFORM hybrid_truco_challenge.publish(instance_id);
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.spawn(uuid, jsonb, jsonb, bigint) FROM PUBLIC;
CREATE TABLE IF NOT EXISTS hybrid_truco_challenge.admission_receipt (id uuid PRIMARY KEY, actor uuid NOT NULL, request jsonb NOT NULL, result jsonb, now bigint NOT NULL);
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.truco_challenge_offer(challenge_id uuid, target uuid, variant text, talk text, seating text DEFAULT '1v1') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE current_actor uuid := public.auth_uid(); admission_id uuid; request_value jsonb; prior hybrid_truco_challenge.admission_receipt; answer jsonb;
BEGIN

IF current_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501'; END IF;
admission_id := challenge_id;
IF admission_id IS NULL THEN RAISE EXCEPTION 'admission identity required'; END IF;
request_value := jsonb_build_object('challenge_id', challenge_id, 'target', target, 'variant', variant, 'talk', talk, 'seating', seating);
-- Its players, before its checks read where they sit.
PERFORM hybrid_truco_challenge.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(jsonb_build_object('inviter', current_actor, 'target', target))) || current_actor);
PERFORM 1 FROM "hybrid_truco_presence"."instance" WHERE "id" IN (current_actor, target) ORDER BY "id" FOR UPDATE;
INSERT INTO hybrid_truco_challenge.admission_receipt (id, actor, request, now) VALUES (admission_id, current_actor, request_value, hybrid_truco_challenge.clock()) ON CONFLICT DO NOTHING;
SELECT * INTO STRICT prior FROM hybrid_truco_challenge.admission_receipt r WHERE r.id = admission_id FOR UPDATE;
IF prior.actor <> current_actor OR prior.request <> request_value THEN
 RAISE EXCEPTION 'admission id reused with different input or owner' USING ERRCODE = '42501'; END IF;
IF prior.result IS NOT NULL THEN RETURN prior.result; END IF;
IF (target IS NOT NULL AND current_actor <> target) IS NOT TRUE THEN
RAISE EXCEPTION 'invalid challenge participants';
END IF;
IF (talk ~ '^[0-9a-f]{16}$') IS NOT TRUE THEN
RAISE EXCEPTION 'invalid table talk';
END IF;
IF (NOT EXISTS (SELECT FROM hybrid_truco_match.instance g WHERE g.state->>'talk' = talk) AND NOT EXISTS (SELECT FROM hybrid_truco_challenge.instance c WHERE c.state->>'talk' = talk)) IS NOT TRUE THEN
RAISE EXCEPTION 'talk_taken';
END IF;
IF (variant IN ('mineiro', 'paulista', 'gaucho', 'truc', 'argentino', 'uruguayo', 'paraguayo', 'douradinha', 'douradao') AND seating IN ('1v1', '2v2', '2v2v2') AND ((seating = '2v2v2') = (variant IN ('douradinha', 'douradao')))) IS NOT TRUE THEN
RAISE EXCEPTION 'unsupported online variant';
END IF;
IF (NOT EXISTS (SELECT FROM hybrid_truco_challenge.instance c WHERE c.state->>'phase' = 'offered' AND c.state->>'inviter' = current_actor::text)) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'outgoing_challenge_pending', 'command_id', admission_id);
UPDATE hybrid_truco_challenge.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
IF (hybrid_truco_presence.available(current_actor) AND hybrid_truco_presence.available(target)) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'player_unavailable', 'command_id', admission_id);
UPDATE hybrid_truco_challenge.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
PERFORM hybrid_truco_challenge.spawn(admission_id, jsonb_build_object('inviter', current_actor, 'target', target, 'variant', variant, 'seating', seating, 'talk', talk, 'room', md5('truco_match/' || challenge_id::text)::uuid, 'inviter_name', (SELECT state->>'name' FROM hybrid_truco_presence.instance WHERE id = current_actor), 'target_name', (SELECT state->>'name' FROM hybrid_truco_presence.instance WHERE id = target)), jsonb_build_object('inviter', current_actor, 'target', target));
answer := jsonb_build_object('kind', 'accepted', 'command_id', admission_id);
UPDATE hybrid_truco_challenge.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.truco_challenge_offer(uuid, uuid, text, text, text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_challenge.open() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $open$
DECLARE answer jsonb;
BEGIN
  PERFORM hybrid_truco_challenge.serial();
  IF NEW.kind = 'create' THEN answer := hybrid_truco_challenge.truco_challenge_offer(NEW.instance_id, coalesce(NEW.input::jsonb->>'target')::uuid, coalesce(NEW.input::jsonb->>'variant')::text, coalesce(NEW.input::jsonb->>'talk')::text, coalesce(NEW.input::jsonb->>'seating', '1v1')::text);
  
  ELSE RAISE EXCEPTION 'unknown open kind %', NEW.kind USING ERRCODE = '22023';
  END IF;
  UPDATE public.truco_challenge_open o SET outcome = answer->>'kind', reason = coalesce(answer->>'reason', '') WHERE o.id = NEW.id;
  RETURN NULL;
END;
$open$;
REVOKE ALL ON FUNCTION hybrid_truco_challenge.open() FROM PUBLIC;
