LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE current_actor uuid := public.auth_uid(); admission_id uuid; request_value jsonb; prior hybrid_truco_voice.admission_receipt; answer jsonb;
BEGIN

IF current_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501'; END IF;
admission_id := instance_id;
IF admission_id IS NULL THEN RAISE EXCEPTION 'admission identity required'; END IF;
request_value := jsonb_build_object('instance_id', instance_id);
-- Its players, before its checks read where they sit.
PERFORM hybrid_truco_voice.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(jsonb_build_object('owner', current_actor))) || current_actor);

INSERT INTO hybrid_truco_voice.admission_receipt (id, actor, request, now) VALUES (admission_id, current_actor, request_value, hybrid_truco_voice.clock()) ON CONFLICT DO NOTHING;
