CREATE OR REPLACE FUNCTION hybrid_truco_call.truco_call_offer(call_id uuid, target uuid, room uuid, chair text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $mecha_port$
DECLARE current_actor uuid := public.auth_uid(); admission_id uuid; request_value jsonb; prior hybrid_truco_call.admission_receipt; answer jsonb;
BEGIN

IF current_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501'; END IF;
admission_id := call_id;
IF admission_id IS NULL THEN RAISE EXCEPTION 'admission identity required'; END IF;
request_value := jsonb_build_object('call_id', call_id, 'target', target, 'room', room, 'chair', chair);
-- Its players, before its checks read where they sit.
PERFORM hybrid_truco_call.hold(ARRAY(SELECT value::uuid FROM jsonb_each_text(jsonb_build_object('caller', current_actor, 'target', target))) || current_actor);
PERFORM 1 FROM "hybrid_truco_match"."instance" WHERE "id" IN (room) ORDER BY "id" FOR UPDATE;
INSERT INTO hybrid_truco_call.admission_receipt (id, actor, request, now) VALUES (admission_id, current_actor, request_value, hybrid_truco_call.clock()) ON CONFLICT DO NOTHING;
SELECT * INTO STRICT prior FROM hybrid_truco_call.admission_receipt r WHERE r.id = admission_id FOR UPDATE;
IF prior.actor <> current_actor OR prior.request <> request_value THEN
 RAISE EXCEPTION 'admission id reused with different input or owner' USING ERRCODE = '42501'; END IF;
IF prior.result IS NOT NULL THEN RETURN prior.result; END IF;
IF (target IS NOT NULL AND current_actor <> target) IS NOT TRUE THEN
RAISE EXCEPTION 'invalid call participants';
END IF;
IF (EXISTS (SELECT FROM hybrid_truco_match.member m WHERE m.instance_id = room AND m.actor = current_actor)) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'not_seated', 'command_id', admission_id);
UPDATE hybrid_truco_call.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
IF (EXISTS (SELECT FROM hybrid_truco_voice.instance v WHERE v.id = current_actor AND v.state->>'room' = room::text)) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'not_seated', 'command_id', admission_id);
UPDATE hybrid_truco_call.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
IF (EXISTS (SELECT FROM hybrid_truco_match.instance g WHERE g.id = room AND g.state->>'phase' = 'waiting' AND g.state->'seats' ? chair) AND NOT EXISTS (SELECT FROM hybrid_truco_match.member m WHERE m.instance_id = room AND m.seat = chair)) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'chair_taken', 'command_id', admission_id);
UPDATE hybrid_truco_call.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
IF (NOT EXISTS (SELECT FROM hybrid_truco_call.instance c WHERE c.state->>'phase' = 'offered' AND c.state->>'room' = room::text AND c.state->>'chair' = chair)) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'chair_called', 'command_id', admission_id);
UPDATE hybrid_truco_call.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
IF (hybrid_truco_presence.available(target)) IS NOT TRUE THEN
answer := jsonb_build_object('kind', 'rejected', 'reason', 'player_unavailable', 'command_id', admission_id);
UPDATE hybrid_truco_call.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END IF;
PERFORM hybrid_truco_call.spawn(admission_id, jsonb_build_object('caller', current_actor, 'target', target, 'room', room, 'chair', chair, 'variant', (SELECT state->>'variant' FROM hybrid_truco_match.instance WHERE id = room), 'seating', (SELECT state->>'seating' FROM hybrid_truco_match.instance WHERE id = room), 'caller_name', (SELECT state->>'name' FROM hybrid_truco_voice.instance WHERE id = current_actor AND state->>'room' = room::text), 'target_name', (SELECT state->>'name' FROM hybrid_truco_presence.instance WHERE id = target)), jsonb_build_object('caller', current_actor, 'target', target));
answer := jsonb_build_object('kind', 'accepted', 'command_id', admission_id);
UPDATE hybrid_truco_call.admission_receipt r SET result = answer WHERE r.id = admission_id;
RETURN answer;
END;
$mecha_port$;
REVOKE ALL ON FUNCTION hybrid_truco_call.truco_call_offer(uuid, uuid, uuid, text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_call.open() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $open$
DECLARE answer jsonb;
BEGIN
  PERFORM hybrid_truco_call.serial();
  IF NEW.kind = 'create' THEN answer := hybrid_truco_call.truco_call_offer(NEW.instance_id, coalesce(NEW.input::jsonb->>'target')::uuid, coalesce(NEW.input::jsonb->>'room')::uuid, coalesce(NEW.input::jsonb->>'chair')::text);
  
  ELSE RAISE EXCEPTION 'unknown open kind %', NEW.kind USING ERRCODE = '22023';
  END IF;
  UPDATE public.truco_call_open o SET outcome = answer->>'kind', reason = coalesce(answer->>'reason', '') WHERE o.id = NEW.id;
  RETURN NULL;
END;
$open$;
REVOKE ALL ON FUNCTION hybrid_truco_call.open() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_call_open_admit AFTER INSERT ON public.truco_call_open FOR EACH ROW EXECUTE FUNCTION hybrid_truco_call.open();
CREATE OR REPLACE TRIGGER truco_call_open_sealed BEFORE UPDATE OR DELETE ON public.truco_call_open FOR EACH ROW EXECUTE FUNCTION hybrid_truco_call.sealed();
CREATE OR REPLACE FUNCTION hybrid_truco_call.arm(instance_id uuid, revision bigint, actions jsonb, at bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $arm$
DECLARE action jsonb; timer text[];
BEGIN
  FOR action IN SELECT value FROM jsonb_array_elements(coalesce(actions, '[]'::jsonb)) LOOP
    timer := regexp_match(coalesce(action->'params'->>'id', action->'params'->>'sendId'), '^xstate\.after\.([^.]+)\.(.+)$');
    IF timer IS NULL THEN RAISE EXCEPTION 'unexpected action %', action; END IF;
    IF action->>'type' = 'xstate.cancel' THEN
      DELETE FROM public.schedule WHERE emits_entity = 'machine_timer_tick' AND emits_values @> (jsonb_build_object('machine', 'truco_call', 'row', jsonb_build_object('id', instance_id::text)) || jsonb_build_object('state', timer[2], 'delay', timer[1]));
    ELSIF action->>'type' = 'xstate.raise' THEN
      INSERT INTO public.schedule (name, due_at, max_lateness_seconds, emits_entity, emits_values)
        VALUES ('machine:' || 'truco_call' || ':' || instance_id::text || ':' || revision::text || ':' || (action->'params'->>'id'),
          to_timestamp((at + (action->'params'->>'delay')::bigint) / 1000.0), 2147483647, 'machine_timer_tick', jsonb_build_object('machine', 'truco_call', 'row', jsonb_build_object('id', instance_id::text)) || jsonb_build_object('state', timer[2], 'delay', timer[1]));
    ELSE RAISE EXCEPTION 'unexpected action %', action;
    END IF;
  END LOOP;
END;
$arm$;
REVOKE ALL ON FUNCTION hybrid_truco_call.arm(uuid, bigint, jsonb, bigint) FROM PUBLIC;
CREATE OR REPLACE FUNCTION hybrid_truco_call.fire() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $fire$
DECLARE instance_id uuid;
BEGIN
  PERFORM hybrid_truco_call.serial();
  IF NEW.machine <> 'truco_call' OR NEW.late THEN RETURN NEW; END IF;
  instance_id := (NEW."row"->>'id')::uuid;
  -- Its players, then the instance, as a step takes them: a step that left
  -- the timer's state has cancelled its schedule by the time both are held.
  PERFORM hybrid_truco_call.hold_instance(instance_id);
  PERFORM 1 FROM hybrid_truco_call.instance i WHERE i.id = instance_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  DELETE FROM public.schedule WHERE name = NEW.schedule AND emits_entity = 'machine_timer_tick';
  IF NOT FOUND THEN RETURN NEW; END IF;
  -- The tick's instant is when the ticker found the delay met, whatever the
  -- database's clock reads. The step runs when the tick was decided, its
  -- transaction's clock(), and never before that instant: a late tick run at
  -- the instant would start the next state's timers in the past.
  PERFORM hybrid_truco_call.deliver(instance_id, jsonb_build_object('kind', 'xstate.after.' || NEW.delay || '.' || NEW.state, 'payload', '{}'::jsonb),
    greatest(round(extract(epoch FROM NEW.tick_at) * 1000)::bigint, hybrid_truco_call.clock()));
  RETURN NEW;
END;
$fire$;
REVOKE ALL ON FUNCTION hybrid_truco_call.fire() FROM PUBLIC;
CREATE OR REPLACE TRIGGER truco_call_timer_fire AFTER INSERT ON public.machine_timer_tick FOR EACH ROW EXECUTE FUNCTION hybrid_truco_call.fire();

